GRAM = [
("B1", "원인·결과 연결어 — à cause de / grâce à / donc / du coup / résultat", "« C'est à cause de la dame de tout à l'heure ? » (부정적 원인) / « Avec ce mois de mars, la trésorerie respire » (원인 + 결과). « Les plats sortent en retard, donc les clients râlent, donc on stresse. » 처럼 donc 를 연쇄해 인과를 이어 갈 수 있다. 구어에서는 « du coup » 가 가장 자주 쓰이며 « Et du coup, on fait des erreurs. » 처럼 문두에서 결과를 이끈다."),
("B1", "부정 표현 ne ... pas plus de, ne ... même pas", "« Je n'ai pas dormi plus de six heures. » 는 상한선을, « Il n'a même pas pris son café. » 는 기대에 못 미치는 극단을 보여 준다. 구어에서는 ne 를 생략해 « J'ai pas dormi plus de six heures » 처럼도 말한다."),
("B2", "비교의 plus ... que prévu / plus vite que", "« On rembourse déjà plus vite que prévu. » 형용사·부사 + que + 과거분사는 '예상·계획보다'의 표현. « On en faisait cinquante en décembre » 처럼 en 으로 수량을 받는 구문도 같이 익힌다."),
("B2", "접속법 ne tienne pas — peur que + 접속법", "« Peur qu'on ne tienne pas le rythme. » peur que 뒤는 접속법이다. 구어에서는 ne 를 생략하고 « qu'on tienne pas » 로 말한다. 정중체 ↔ 구어: « Je crains que nous ne tenions pas... » ↔ « J'ai peur qu'on tienne pas... »"),
("B1", "대명동사 명령형 — Va te laver les mains", "« Va te laver les mains, on commence. » 긍정 명령에서는 « lave-toi », 연속 동작에서는 « Va te laver ». 주방·홀의 짧은 지시는 대명동사 + 인칭대명사 위치를 자연스럽게 익히는 데 좋다."),
("B2", "수 표현과 비율 — soixante-dix, quatre-vingts", "« On limite les réservations à soixante-dix couverts. » « J'ai quatre-vingts couverts à préparer. » 70(soixante-dix), 80(quatre-vingts)은 프랑스 프랑스어 특유의 20진법이다. 끝의 s 는 quatre-vingts 에서만 붙고 뒤에 수가 오면 탈락(quatre-vingt-un)."),
("B1", "tu + 현재 / 반문 — Tu pouvais pas ... ?", "« Tu pouvais pas le dire plus tôt ? » 는 불평을 담은 과거 반문. 반과거(imparfait) 의문은 '그럴 수 있었잖아?' 라는 비난의 뉘앙스. 정중 ↔ « Auriez-vous pu me le dire plus tôt ? »"),
]

